/**
 * Volunteer Survey Cleaner
 * 
 * Reads "Raw" sheet (columns A–F), normalises fields, flags duplicates,
 * and writes results to "Clean" and "Review" sheets.
 *
 * Raw is never modified.
 *
 * Menu: Volunteer Tools ▸ Clean Survey Data
 */

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu('Volunteer Tools')
    .addItem('Clean Survey Data', 'cleanSurveyData')
    .addToUi();
}

/* ───────────────────────── main ───────────────────────── */

function cleanSurveyData() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  // ── source sheets ──
  const raw = ss.getSheetByName('Raw');
  if (!raw) { SpreadsheetApp.getUi().alert('No sheet named "Raw" found.'); return; }

  const parkMapSheet = ss.getSheetByName('ParkMap');
  if (!parkMapSheet) { SpreadsheetApp.getUi().alert('No sheet named "ParkMap" found.'); return; }

  // ── build park lookup (key → canonical) ──
  const parkData = parkMapSheet.getDataRange().getValues();
  const parkMap = {};
  for (let i = 0; i < parkData.length; i++) {
    const key = String(parkData[i][0]).toLowerCase().replace(/[^a-z]/g, '');
    if (key) parkMap[key] = String(parkData[i][1]);
  }

  // ── read raw data (skip header row) ──
  const data = raw.getDataRange().getValues();
  const headers = data[0];
  const colIndex = buildColumnIndex(headers);
  const rows = data.slice(1);

  if (rows.length === 0) { SpreadsheetApp.getUi().alert('Raw sheet has no data rows.'); return; }

  // ── first pass: normalise every row ──
  const processed = rows.map((r, i) => processRow(r, i, colIndex, parkMap));

  // ── second pass: duplicate detection ──
  markDuplicates(processed);

  // ── third pass: superseded flag (keep most recent per email) ──
  markSuperseded(processed);

  // ── fourth pass: overall REVIEW flag ──
  processed.forEach(r => {
    const dominated = r.superseded === 'SUPERSEDED';
    const hasReview = [r.normJoined, r.cleanPhone, r.parsedTs === null ? 'REVIEW' : '',
                       r.canonPark].some(v => v === 'REVIEW');
    const isDup = r.dupEmail !== '' || r.dupNameTime !== '';

    // missing-email collision: email blank and name matches another row's name
    const missingEmailCollision = r.email === '' && r.dupNameTime !== '';

    r.reviewFlag = (hasReview || isDup || missingEmailCollision || dominated) ? 'REVIEW' : 'OK';
    // A row goes to Clean only if reviewFlag === 'OK'
  });

  // ── write output sheets ──
  const outHeaders = [
    'Timestamp', 'Name', 'Email', 'JoinedBefore', 'Phone', 'PreferredPark',
    'ParsedTimestamp', 'NormalizedJoined', 'CleanPhone', 'CanonicalPark',
    'DUP_email', 'DUP_name_time', 'SUPERSEDED', 'REVIEW_FLAG'
  ];

  const toOutputRow = (r) => [
    r.raw[colIndex.timestamp],
    r.raw[colIndex.name],
    r.raw[colIndex.email],
    r.raw[colIndex.joinedBefore],
    r.raw[colIndex.phone],
    r.raw[colIndex.preferredPark],
    r.parsedTs !== null ? r.parsedTs : 'REVIEW',
    r.normJoined,
    r.cleanPhone,
    r.canonPark,
    r.dupEmail,
    r.dupNameTime,
    r.superseded,
    r.reviewFlag
  ];

  const cleanRows = processed.filter(r => r.reviewFlag === 'OK').map(toOutputRow);
  const reviewRows = processed.filter(r => r.reviewFlag === 'REVIEW').map(toOutputRow);

  writeSheet(ss, 'Clean', outHeaders, cleanRows);
  writeSheet(ss, 'Review', outHeaders, reviewRows);

  SpreadsheetApp.getUi().alert(
    `Done.\n\nClean: ${cleanRows.length} rows\nReview: ${reviewRows.length} rows`
  );
}

/* ───────────────── column index builder ───────────────── */

function buildColumnIndex(headers) {
  const norm = headers.map(h => String(h).toLowerCase().replace(/[^a-z]/g, ''));
  const find = (target) => {
    const idx = norm.indexOf(target);
    if (idx === -1) throw new Error('Missing column: ' + target);
    return idx;
  };
  return {
    timestamp:     find('timestamp'),
    name:          find('name'),
    email:         find('email'),
    joinedBefore:  find('joinedbefore'),
    phone:         find('phone'),
    preferredPark: find('preferredpark')
  };
}

/* ───────────────── row-level processing ───────────────── */

function processRow(row, index, col, parkMap) {
  const result = {
    raw: row,
    index: index,
    // keys for duplicate detection
    emailKey: String(row[col.email]).trim().toLowerCase(),
    nameKey:  String(row[col.name]).trim().toLowerCase().replace(/\s+/g, ' '),
    email:    String(row[col.email]).trim(),
    // normalised fields
    parsedTs:   null,
    normJoined: 'REVIEW',
    cleanPhone: 'REVIEW',
    canonPark:  'REVIEW',
    // flags
    dupEmail:   '',
    dupNameTime:'',
    superseded: '',
    reviewFlag: ''
  };

  // ── timestamp ──
  result.parsedTs = parseTimestamp(row[col.timestamp]);

  // ── JoinedBefore ──
  const jb = String(row[col.joinedBefore]).trim().toLowerCase();
  if (/^y(es)?$/.test(jb))       result.normJoined = 'Yes';
  else if (/^no?$/.test(jb))     result.normJoined = 'No';
  else if (jb === '')            result.normJoined = 'REVIEW';

  // ── phone ──
  const digits = String(row[col.phone]).replace(/\D/g, '');
  let phone = digits;
  if (phone.length === 11 && phone[0] === '1') phone = phone.substring(1);
  result.cleanPhone = (phone.length === 10) ? phone : 'REVIEW';

  // ── park ──
  const parkRaw = String(row[col.preferredPark]).trim();
  if (parkRaw === '') {
    result.canonPark = 'REVIEW';
  } else {
    const key = parkRaw.toLowerCase().replace(/[^a-z]/g, '');
    result.canonPark = parkMap.hasOwnProperty(key) ? parkMap[key] : 'REVIEW';
  }

  return result;
}

/* ───────────────── timestamp parser ───────────────── */

function parseTimestamp(val) {
  // If Sheets already gave us a Date object, use it
  if (val instanceof Date && !isNaN(val.getTime())) return val;

  const s = String(val).trim();
  if (s === '') return null;

  // Try native parse (handles many formats including "03-Mar-2021")
  let d = new Date(s);
  if (!isNaN(d.getTime())) return d;

  // Try M/D/YY + optional time  e.g. "4/3/21 09:12"
  const m = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})\s*(\d{1,2}:\d{2})?/);
  if (m) {
    let year = parseInt(m[3], 10);
    if (year < 100) year += 2000;
    const dateStr = m[1] + '/' + m[2] + '/' + year + (m[4] ? ' ' + m[4] : '');
    d = new Date(dateStr);
    if (!isNaN(d.getTime())) return d;
  }

  return null;  // will become REVIEW
}

/* ───────────────── duplicate detection ───────────────── */

function markDuplicates(rows) {
  // ── same email ──
  const emailGroups = {};
  rows.forEach((r, i) => {
    if (r.emailKey === '') return;
    if (!emailGroups[r.emailKey]) emailGroups[r.emailKey] = [];
    emailGroups[r.emailKey].push(i);
  });
  for (const key in emailGroups) {
    if (emailGroups[key].length > 1) {
      emailGroups[key].forEach(i => { rows[i].dupEmail = 'DUP-email'; });
    }
  }

  // ── same name within 10 minutes ──
  const nameGroups = {};
  rows.forEach((r, i) => {
    if (r.nameKey === '' || r.parsedTs === null) return;
    if (!nameGroups[r.nameKey]) nameGroups[r.nameKey] = [];
    nameGroups[r.nameKey].push(i);
  });
  const TEN_MIN_MS = 10 * 60 * 1000;
  for (const key in nameGroups) {
    const group = nameGroups[key];
    if (group.length < 2) continue;
    for (let a = 0; a < group.length; a++) {
      for (let b = a + 1; b < group.length; b++) {
        const diff = Math.abs(rows[group[a]].parsedTs.getTime() - rows[group[b]].parsedTs.getTime());
        if (diff <= TEN_MIN_MS) {
          rows[group[a]].dupNameTime = 'DUP-name-time';
          rows[group[b]].dupNameTime = 'DUP-name-time';
        }
      }
    }
  }
}

/* ───────────────── superseded flag ───────────────── */

function markSuperseded(rows) {
  // For each email group, the row with the latest timestamp is kept;
  // all others are SUPERSEDED.
  const emailGroups = {};
  rows.forEach((r, i) => {
    if (r.emailKey === '') return;
    if (!emailGroups[r.emailKey]) emailGroups[r.emailKey] = [];
    emailGroups[r.emailKey].push(i);
  });

  for (const key in emailGroups) {
    const group = emailGroups[key];
    if (group.length < 2) continue;

    // find the index with the latest parsedTs
    let latestIdx = group[0];
    let latestTime = rows[latestIdx].parsedTs ? rows[latestIdx].parsedTs.getTime() : -Infinity;
    for (let j = 1; j < group.length; j++) {
      const t = rows[group[j]].parsedTs ? rows[group[j]].parsedTs.getTime() : -Infinity;
      if (t > latestTime) { latestTime = t; latestIdx = group[j]; }
    }

    group.forEach(i => {
      if (i !== latestIdx) rows[i].superseded = 'SUPERSEDED';
    });
  }
}

/* ───────────────── sheet writer ───────────────── */

function writeSheet(ss, name, headers, dataRows) {
  let sheet = ss.getSheetByName(name);
  if (sheet) {
    sheet.clear();
  } else {
    sheet = ss.insertSheet(name);
  }

  sheet.appendRow(headers);

  if (dataRows.length > 0) {
    sheet.getRange(2, 1, dataRows.length, headers.length).setValues(dataRows);
  }

  // format ParsedTimestamp column (column G = index 7) as datetime
  if (dataRows.length > 0) {
    sheet.getRange(2, 7, dataRows.length, 1).setNumberFormat('M/d/yyyy HH:mm');
  }

  // freeze header
  sheet.setFrozenRows(1);

  // bold header
  sheet.getRange(1, 1, 1, headers.length).setFontWeight('bold');

  // auto-resize
  for (let c = 1; c <= headers.length; c++) {
    sheet.autoResizeColumn(c);
  }
}
