  if (!parkMapSheet) { SpreadsheetApp.getUi().alert('No sheet named "ParkMap" found.'); return; }

  // ── build park lookup (key → canonical), skip header row ──
  const parkData = parkMapSheet.getDataRange().getValues();
  const parkMap = {};
  for (let i = 0; i < parkData.length; i++) {
    // skip any row whose first cell looks like a header
    const raw0 = String(parkData[i][0]).trim().toLowerCase();
    if (i === 0 && /^key$/i.test(parkData[i][0].toString().trim())) continue;
    const key = raw0.replace(/[^a-z]/g, '');
    if (key) parkMap[key] = String(parkData[i][1]).trim();
