/**
 * Which duplicate to keep when multiple rows share an email:
 *   'latest'   – keep the row with the most recent timestamp (default)
 *   'earliest' – keep the row with the oldest timestamp
 */
const KEEP_DUPLICATE = 'latest';

/**
 * Time window (in minutes) for name-based duplicate detection.
 */
const NAME_DUP_WINDOW_MINUTES = 10;

/* ═══════════════════════════════════════════════ */

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu('Volunteer Tools')
    .addItem('Clean Survey Data', 'cleanSurveyData')
    .addToUi();
}

function cleanSurveyData() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var ui = SpreadsheetApp.getUi();

  var raw = ss.getSheetByName('Raw');
  if (!raw) { ui.alert('No sheet named "Raw" found.'); return; }

  var parkMapSheet = ss.getSheetByName('ParkMap');
  if (!parkMapSheet) { ui.alert('No sheet named "ParkMap" found.'); return; }

  var parkData = parkMapSheet.getDataRange().getValues();
  var parkMap = buildParkMap(parkData);

  var data = raw.getDataRange().getValues();
  var headers = data[0];
  var col = buildColumnIndex(headers);
  var rows = data.slice(1);

  if (rows.length === 0) { ui.alert('Raw sheet has no data rows.'); return; }

  var processed = [];
  for (var i = 0; i < rows.length; i++) {
    processed.push(processRow(rows[i], i, col, parkMap));
  }

  var groups = markDuplicates(processed);
  computeDiffs(processed, groups.emailGroups, groups.nameTimeGroups, col);
  markSuperseded(processed, groups.emailGroups);

  for (var j = 0; j < processed.length; j++) {
    var r = processed[j];
    var hasReview = (r.normJoined === 'REVIEW' || r.cleanPhone === 'REVIEW' ||
                     r.parsedTs === null || r.canonPark === 'REVIEW');
    var isDup = (r.dupEmail !== '' || r.dupNameTime !== '');
    var missingEmailCollision = (r.email === '' && r.dupNameTime !== '');
    var dominated = (r.superseded === 'SUPERSEDED');
    r.reviewFlag = (hasReview || isDup || missingEmailCollision || dominated) ? 'REVIEW' : 'OK';
  }

  var outHeaders = [
    'RawRow',
    'Timestamp', 'Name', 'Email', 'JoinedBefore', 'Phone', 'PreferredPark',
    'ParsedTimestamp', 'NormalizedJoined', 'CleanPhone', 'CanonicalPark',
    'DUP_email', 'DUP_name_time', 'Diffs', 'SUPERSEDED', 'REVIEW_FLAG'
  ];

  var cleanRows = [];
  var reviewRows = [];

  for (var k = 0; k < processed.length; k++) {
    var row = toOutputRow(processed[k], col);
    if (processed[k].reviewFlag === 'OK') {
      cleanRows.push(row);
    } else {
      reviewRows.push(row);
    }
  }

  writeSheet(ss, 'Clean', outHeaders, cleanRows);
  writeSheet(ss, 'Review', outHeaders, reviewRows);

  ui.alert(
    'Done.  (Keep mode: ' + KEEP_DUPLICATE +
    ', name-dup window: ' + NAME_DUP_WINDOW_MINUTES + ' min)\n\n' +
    'Clean: ' + cleanRows.length + ' rows\n' +
    'Review: ' + reviewRows.length + ' rows'
  );
}

function toOutputRow(r, col) {
  return [
    r.rawRow,
    r.raw[col.timestamp],
    r.raw[col.name],
    r.raw[col.email],
    r.raw[col.joinedBefore],
    r.raw[col.phone],
    r.raw[col.preferredPark],
    r.parsedTs !== null ? r.parsedTs : 'REVIEW',
    r.normJoined,
    r.cleanPhone,
    r.canonPark,
    r.dupEmail,
    r.dupNameTime,
    r.diffs,
    r.superseded,
    r.reviewFlag
  ];
}

/* ───────────── ParkMap ───────────── */

function buildParkMap(parkData) {
  var map = {};
  var skipFirst = shouldSkipParkMapHeader(parkData);
  var start = skipFirst ? 1 : 0;
  for (var i = start; i < parkData.length; i++) {
    var key = String(parkData[i][0]).trim().toLowerCase().replace(/[^a-z]/g, '');
    if (key) map[key] = String(parkData[i][1]).trim();
  }
  return map;
}

function shouldSkipParkMapHeader(parkData) {
  if (parkData.length < 2) return false;
  var row1a = String(parkData[0][0]).trim();
  var row2a = String(parkData[1][0]).trim();
  if (row1a === '' || row2a === '') return false;
  if (!/[a-zA-Z]/.test(row1a)) return false;
  var norm1 = row1a.toLowerCase().replace(/[^a-z]/g, '');
  var norm2 = row2a.toLowerCase().replace(/[^a-z]/g, '');
  return norm1 !== norm2;
}

/* ───────────── Column index ───────────── */

function buildColumnIndex(headers) {
  var norm = [];
  for (var i = 0; i < headers.length; i++) {
    norm.push(String(headers[i]).toLowerCase().replace(/[^a-z]/g, ''));
  }
  function find(target) {
    var idx = norm.indexOf(target);
    if (idx === -1) throw new Error('Missing column: ' + target);
    return idx;
  }
  return {
    timestamp: find('timestamp'),
    name: find('name'),
    email: find('email'),
    joinedBefore: find('joinedbefore'),
    phone: find('phone'),
    preferredPark: find('preferredpark')
  };
}

/* ───────────── Row processing ───────────── */

function processRow(row, index, col, parkMap) {
  var result = {
    raw: row,
    index: index,
    rawRow: index + 2,
    emailKey: String(row[col.email]).trim().toLowerCase(),
    nameKey: String(row[col.name]).trim().toLowerCase().replace(/\s+/g, ' '),
    email: String(row[col.email]).trim(),
    parsedTs: null,
    normJoined: 'REVIEW',
    cleanPhone: 'REVIEW',
    canonPark: 'REVIEW',
    dupEmail: '',
    dupNameTime: '',
    diffs: '',
    superseded: '',
    reviewFlag: ''
  };

  result.parsedTs = parseTimestamp(row[col.timestamp]);

  var jb = String(row[col.joinedBefore]).trim().toLowerCase();
  if (/^y(es)?$/.test(jb)) result.normJoined = 'Yes';
  else if (/^no?$/.test(jb)) result.normJoined = 'No';

  var digits = String(row[col.phone]).replace(/\D/g, '');
  if (digits.length === 11 && digits[0] === '1') digits = digits.substring(1);
  if (digits.length === 10) result.cleanPhone = digits;

  var parkRaw = String(row[col.preferredPark]).trim();
  if (parkRaw !== '') {
    var key = parkRaw.toLowerCase().replace(/[^a-z]/g, '');
    if (parkMap.hasOwnProperty(key)) result.canonPark = parkMap[key];
  }

  return result;
}

/* ───────────── Timestamp parser ───────────── */

function parseTimestamp(val) {
  if (val instanceof Date && !isNaN(val.getTime())) return val;
  var s = String(val).trim();
  if (s === '') return null;
  var d = new Date(s);
  if (!isNaN(d.getTime())) return d;
  var m = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})\s*(\d{1,2}:\d{2})?/);
  if (m) {
    var year = parseInt(m[3], 10);
    if (year < 100) year += 2000;
    var dateStr = m[1] + '/' + m[2] + '/' + year + (m[4] ? ' ' + m[4] : '');
    d = new Date(dateStr);
    if (!isNaN(d.getTime())) return d;
  }
  return null;
}

/* ───────────── Duplicate detection ───────────── */

function markDuplicates(rows) {
  var emailGroups = {};
  var i, key, group;

  for (i = 0; i < rows.length; i++) {
    if (rows[i].emailKey === '') continue;
    if (!emailGroups[rows[i].emailKey]) emailGroups[rows[i].emailKey] = [];
    emailGroups[rows[i].emailKey].push(i);
  }
  for (key in emailGroups) {
    if (emailGroups[key].length > 1) {
      for (i = 0; i < emailGroups[key].length; i++) {
        rows[emailGroups[key][i]].dupEmail = 'DUP-email';
      }
    }
  }

  var nameGroups = {};
  for (i = 0; i < rows.length; i++) {
    if (rows[i].nameKey === '' || rows[i].parsedTs === null) continue;
    if (!nameGroups[rows[i].nameKey]) nameGroups[rows[i].nameKey] = [];
    nameGroups[rows[i].nameKey].push(i);
  }

  var windowMs = NAME_DUP_WINDOW_MINUTES * 60 * 1000;
  var ufParent = {};

  function ufFind(x) {
    if (ufParent[x] === undefined) ufParent[x] = x;
    while (ufParent[x] !== x) {
      ufParent[x] = ufParent[ufParent[x]];
      x = ufParent[x];
    }
    return x;
  }
  function ufUnion(a, b) {
    var ra = ufFind(a), rb = ufFind(b);
    if (ra !== rb) ufParent[ra] = rb;
  }

  var flaggedSet = {};

  for (key in nameGroups) {
    group = nameGroups[key];
    if (group.length < 2) continue;
    for (var a = 0; a < group.length; a++) {
      for (var b = a + 1; b < group.length; b++) {
        var diff = Math.abs(rows[group[a]].parsedTs.getTime() - rows[group[b]].parsedTs.getTime());
        if (diff <= windowMs) {
          rows[group[a]].dupNameTime = 'DUP-name-time';
          rows[group[b]].dupNameTime = 'DUP-name-time';
          ufUnion(group[a], group[b]);
          flaggedSet[group[a]] = true;
          flaggedSet[group[b]] = true;
        }
      }
    }
  }

  var nameTimeGroups = {};
  for (var idx in flaggedSet) {
    var root = ufFind(parseInt(idx, 10));
    if (!nameTimeGroups[root]) nameTimeGroups[root] = [];
    nameTimeGroups[root].push(parseInt(idx, 10));
  }

  return { emailGroups: emailGroups, nameTimeGroups: nameTimeGroups };
}

/* ───────────── Diff computation ───────────── */

function computeDiffs(rows, emailGroups, nameTimeGroups, col) {
  var colDefs = [
    { key: col.timestamp, label: 'Timestamp' },
    { key: col.name, label: 'Name' },
    { key: col.email, label: 'Email' },
    { key: col.joinedBefore, label: 'JoinedBefore' },
    { key: col.phone, label: 'Phone' },
    { key: col.preferredPark, label: 'PreferredPark' }
  ];

  function diffLabelsForGroup(indices) {
    var labels = [];
    for (var c = 0; c < colDefs.length; c++) {
      var seen = {};
      var count = 0;
      for (var j = 0; j < indices.length; j++) {
        var v = rows[indices[j]].raw[colDefs[c].key];
        var norm;
        if (v instanceof Date) {
          norm = v.getTime().toString();
        } else {
          norm = String(v).trim().toLowerCase();
        }
        if (!seen[norm]) {
          seen[norm] = true;
          count++;
        }
      }
      if (count > 1) labels.push(colDefs[c].label);
    }
    return labels;
  }

  // Accumulator: rowIndex → { label: true }
  var rowDiffs = {};

  function ensureEntry(idx) {
    if (!rowDiffs[idx]) rowDiffs[idx] = {};
  }

  function applyGroupDiffs(groups) {
    for (var key in groups) {
      var group = groups[key];
      if (group.length < 2) continue;
      var labels = diffLabelsForGroup(group);
      for (var g = 0; g < group.length; g++) {
        ensureEntry(group[g]);
        for (var l = 0; l < labels.length; l++) {
          rowDiffs[group[g]][labels[l]] = true;
        }
      }
    }
  }

